// Was generated by DeepSeek AI and modified. The prompt given was: Can you create a JS script for a modal popup form to add assignments.

document.addEventListener('DOMContentLoaded', function() {
    // Get DOM elements
    const addAssignmentBtn = document.getElementById('addAssignmentBtn');
    const assignmentModal = document.getElementById('assignmentModal');
    const closeModal = document.getElementById('closeModal');
    const assignmentForm = document.getElementById('assignmentForm');
    const assignmentList = document.getElementById('assignmentList');
    
    // Sample assignments data
    let assignments = [];
    
    // Show modal when Add Assignment button is clicked
    addAssignmentBtn.addEventListener('click', function() {
        assignmentModal.style.display = 'flex';
    });
    
    // Close modal when X is clicked
    closeModal.addEventListener('click', function() {
        assignmentModal.style.display = 'none';
    });
    
    // Close modal when clicking outside the modal content
    window.addEventListener('click', function(event) {
        if (event.target === assignmentModal) {
            assignmentModal.style.display = 'none';
        }
    });
    
    // Handle form submission
    assignmentForm.addEventListener('submit', function(e) {
        e.preventDefault();
        
        // Get form values
        const title = document.getElementById('title').value;
        const description = document.getElementById('description').value;
        const dueDate = document.getElementById('dueDate').value;
        const course = document.getElementById('course').value;
        
        // Create assignment object
        const assignment = {
            id: Date.now(), // unique ID
            title,
            description,
            dueDate,
            course
        };
        
        // Add to assignments array
        assignments.push(assignment);
        
        // Update UI
        renderAssignments();
        
        // Reset form and close modal
        assignmentForm.reset();
        assignmentModal.style.display = 'none';
        
        // Show confirmation
        alert('Assignment added successfully!');
    });
    
    // Render assignments to the page
    function renderAssignments() {
        if (assignments.length === 0) {
            assignmentList.innerHTML = '<p>No assignments yet. Click "Add New Assignment" to create your first assignment.</p>';
            return;
        }
        
        assignmentList.innerHTML = '';
        
        assignments.forEach(assignment => {
            const assignmentElement = document.createElement('div');
            assignmentElement.classList.add('assignment-item');
            
            // Format the date for display
            const dueDate = new Date(assignment.dueDate).toLocaleDateString('en-US', {
                year: 'numeric',
                month: 'long',
                day: 'numeric'
            });
            
            assignmentElement.innerHTML = `
                <h3>${assignment.title}</h3>
                <p><strong>Course:</strong> ${assignment.course}</p>
                <p>${assignment.description}</p>
                <p><strong>Due:</strong> <span class="due-date">${dueDate}</span></p>
            `;
            
            assignmentList.appendChild(assignmentElement);
        });
    }
    
    // Initial render
    renderAssignments();
});